import React from "react";
import { createRoot } from "react-dom/client";
import { SolutionGrids } from "./SolutionGrids";

const elem = document.getElementById("solution-grids-root");
if (elem) {
  const root = createRoot(elem);
  root.render(<SolutionGrids />);
} else {
  console.error(
    "Could not mount App because #solution-grids-root was nowhere to be found",
  );
}
